css:
html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: transparent !important;
  pointer-events: none;
}

.door-widget,
.door-widget * {
  box-sizing: border-box;
}

.door-widget {
  --door-fill: #D7D8DB;
  --door-text: #000000;

  display: flex;
  align-items: center;
  justify-content: center;

  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;

  background: transparent;
  opacity: var(--w-opacity, 1);

  pointer-events: none;
  user-select: none;
}

.door-svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: hidden;

  background: transparent;
  shape-rendering: geometricPrecision;
  pointer-events: none;
}

.door-frame {
  fill: var(--door-fill);
  stroke: #01524F;
  stroke-width: 2;
}

.door-reflection {
  fill: none;
  stroke: #FFFFFF;
  stroke-width: 1.5;
  stroke-linecap: round;
  opacity: 0.35;
}

.door-shadow {
  fill: none;
  stroke: #000000;
  stroke-width: 2;
  stroke-linecap: round;
  opacity: 0.12;
}

.door-title,
.door-state {
  font-family:
    Bahnschrift,
    "DIN Alternate",
    Consolas,
    "Liberation Mono",
    monospace;

  font-size: 20px;
  font-style: normal;
  font-kerning: normal;

  fill: var(--door-text);
}

.door-title {
  font-weight: 400;
  letter-spacing: 0.3px;
}

.door-state {
  font-weight: 700;
  letter-spacing: 0.5px;
}

.door-state {
  fill: var(--door-state-text, #01524F);
}

