"use strict";

(function () {
  const DEFAULT_TITLE = "PUERTA 1";
  const DEFAULT_FILL = "#D7D8DB";
  const BASE_FONT_SIZE = 20;
  const MAX_TEXT_WIDTH = 114;

  let widgetElement = null;
  let titleElement = null;
  let stateElement = null;
  let latestWidget = window.WIDGET || {};

  // Permite interpretar colores HEX, RGB y otros formatos CSS.
  const canvas = document.createElement("canvas");
  canvas.width = 1;
  canvas.height = 1;

  const context = canvas.getContext("2d", {
    willReadFrequently: true
  });

  function isOpen(value) {
    if (value === true || value === 1) {
      return true;
    }

    if (typeof value === "string") {
      const normalized = value.trim().toLowerCase();
      return normalized === "1" || normalized === "true";
    }

    return false;
  }

  function getTitle(widget) {
    if (typeof widget.name !== "string") {
      return DEFAULT_TITLE;
    }

    return widget.name.trim() || DEFAULT_TITLE;
  }

  function getAppearanceColor(widget) {
    if (
      typeof widget.color === "string" &&
      widget.color.trim()
    ) {
      return widget.color.trim();
    }

    const injectedColor = getComputedStyle(widgetElement)
      .getPropertyValue("--w-color")
      .trim();

    return injectedColor || DEFAULT_FILL;
  }

  function resolveColor(color) {
    if (!context) {
      return [215, 216, 219];
    }

    // El relleno se mantiene opaco para asegurar el contraste.
    context.clearRect(0, 0, 1, 1);
    context.fillStyle = DEFAULT_FILL;
    context.fillRect(0, 0, 1, 1);

    context.fillStyle = DEFAULT_FILL;

    if (CSS.supports("color", color)) {
      context.fillStyle = color;
    }

    context.fillRect(0, 0, 1, 1);

    const pixel = context.getImageData(0, 0, 1, 1).data;
    return [pixel[0], pixel[1], pixel[2]];
  }

  function linearChannel(value) {
    const channel = value / 255;

    return channel <= 0.04045
      ? channel / 12.92
      : Math.pow((channel + 0.055) / 1.055, 2.4);
  }

function applyColors(widget) {
  const rgb = resolveColor(getAppearanceColor(widget));

  function luminance(color) {
    return (
      0.2126 * linearChannel(color[0]) +
      0.7152 * linearChannel(color[1]) +
      0.0722 * linearChannel(color[2])
    );
  }

  function contrast(first, second) {
    return (
      (Math.max(first, second) + 0.05) /
      (Math.min(first, second) + 0.05)
    );
  }

  const backgroundLuminance = luminance(rgb);

  // Título: negro o blanco.
  const titleColor =
    contrast(backgroundLuminance, 0) >=
    contrast(backgroundLuminance, 1)
      ? "#000000"
      : "#FFFFFF";

  // Estado: verde oscuro o gris claro.
  const darkLuminance = luminance([1, 82, 79]);
  const lightLuminance = luminance([220, 227, 235]);

  const stateColor =
    contrast(backgroundLuminance, darkLuminance) >=
    contrast(backgroundLuminance, lightLuminance)
      ? "#01524F"
      : "#DCE3EB";

  widgetElement.style.setProperty(
    "--door-fill",
    "rgb(" + rgb.join(", ") + ")"
  );

  widgetElement.style.setProperty(
    "--door-text",
    titleColor
  );

  widgetElement.style.setProperty(
    "--door-state-text",
    stateColor
  );
}

  function fitTexts() {
    if (!titleElement || !stateElement) {
      return;
    }

    titleElement.style.fontSize = BASE_FONT_SIZE + "px";
    stateElement.style.fontSize = BASE_FONT_SIZE + "px";

    const widestText = Math.max(
      titleElement.getComputedTextLength(),
      stateElement.getComputedTextLength()
    );

    // Reduce ambos por igual si el nombre es largo.
    if (widestText > MAX_TEXT_WIDTH) {
      const size =
        BASE_FONT_SIZE * MAX_TEXT_WIDTH / widestText;

      titleElement.style.fontSize = size + "px";
      stateElement.style.fontSize = size + "px";
    }
  }

  function render(widget) {
    if (!widgetElement || !titleElement || !stateElement) {
      return;
    }

    const title = getTitle(widget);
    const state = isOpen(widget.value)
      ? "ABIERTA"
      : "CERRADA";

    titleElement.textContent = title;
    stateElement.textContent = state;

    widgetElement.setAttribute(
      "aria-label",
      title + ": " + state
    );

    applyColors(widget);
    fitTexts();
  }

  window.onWidgetUpdate = function (widget) {
    latestWidget = widget || {};
    render(latestWidget);
  };

  function initialize() {
    widgetElement = document.querySelector(".door-widget");
    titleElement = document.getElementById("door-title");
    stateElement = document.getElementById("door-state");

    render(latestWidget);

    if (document.fonts && document.fonts.ready) {
      document.fonts.ready.then(fitTexts);
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      initialize,
      { once: true }
    );
  } else {
    initialize();
  }
})();
